// === Tab: mySketch ===
/*
So this is a project for a paper for SIGBOVIK (https://sigbovik.org/2024/), a
conference for joke CS papers. My project is to let you upload a photo of a
city landmark (masked to just the landmark, try using remove.bg to get one)
and turn it into a bean like Chicago's Cloud Gate, probably a better use of
land than whatever your building was. Paper and video coming soon!

This uses a genetic optimization algorithm to make small changes to the beans
to slowly better approximate the input image. Each is made of some Bezier
segments, combined with a smooth union sdf.

This was my SIGBOVIK project last year: https://github.com/davepagurek/jalgorithm
*/

let renderer
let inputImg
let spheremap
let optimizer
let picker
OPC.slider({ name: 'smoothness', label: 'Smoothness', min: 0, max: 1, step: 0.01, value: 0.33 })
OPC.toggle({ name: 'dilate', label: 'Puff Out Input', value: true })
OPC.toggle({ name: 'optimize', label: 'Run Optimization', value: true })

function preload() {
	spheremap = loadImage('https://openprocessing.org/sketch/193534/files/narthex_equirect.jpg')
	//spheremap = loadImage('https://openprocessing.org/sketch/2223009/files/dusseldorf_bridge.jpg')
	inputImg = loadImage('https://openprocessing.org/sketch/2223009/files/IMG_6828.JPG')
}

function setup() {
  createCanvas(window.innerWidth, window.innerHeight, WEBGL)
	pixelDensity(1)

	optimizer = new BeanFitter(inputImg, dilate)
	renderer = createBeanRenderer()

	input = createFileInput(handleImage)
  input.position(20, 20)
}

function handleImage(file) {
  if (file.type === 'image') {
		let img = createImg(file.data, '', 'anonymous', () => {
			const graphic = createGraphics(img.elt.naturalWidth, img.elt.naturalHeight)
			graphic.image(img, 0, 0)
			img.remove()
			img = graphic.get()
			graphic.remove()
			optimizer.remove()
			optimizer = new BeanFitter(img, dilate)
		})
  }
}

let lastDilate = dilate
function draw() {
	background(255)

	if (lastDilate !== dilate) {
		const oldOptimizer = optimizer
		optimizer = new BeanFitter(optimizer.target, dilate)
		oldOptimizer.remove()
	}
	lastDilate = dilate

	if (optimize) optimizer.optimize()

	push()
	resetMatrix()
	translate(0, -height/2 + 200)
	optimizer.draw()
	pop()

	orbitControl()
	push()
	translate(0, height/3 - 100)
	renderer.draw(optimizer.bestParams, smoothness)
	pop()
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: beanParams ===
class BeanParams {
	constructor(segments, maxThickness) {
		this.minSegments = 1
		this.maxSegments = 8
		this.maxThickness = maxThickness || 1
		this.segments = segments || []
		if (this.segments.length === 0) {
			const numSegments = round(random(this.minSegments, this.maxSegments))
			for (let i = 0; i < numSegments; i++) {
				this.segments.push(new QuadraticBezierParam(
					undefined,
					undefined,
					undefined,
					undefined,
					undefined,
					undefined,
					this.maxThickness,
				))
			}
		}
	}

	mutate(sd) {
		const newSegments = [...this.segments]

		const changeSegments = random() < sd / 5
		if (changeSegments) {
			if (this.segments.length < this.maxSegments && random() < 0.5) {
				newSegments.push(new QuadraticBezierParam(
					undefined,
					undefined,
					undefined,
					undefined,
					undefined,
					undefined,
					this.maxThickness,
				))
			} else if (this.segments.length > this.minSegments) {
				newSegments.splice(floor(random(newSegments.length)), 1)
			}
		} else {
			const toMutate = floor(random(newSegments.length))
			newSegments[toMutate] = newSegments[toMutate].mutate(sd)
		}
		return new BeanParams(newSegments, this.maxThickness)
	}
}

class QuadraticBezierParam {
	constructor(ax, ay, bend, cx, cy, thickness, maxThickness) {
		this.ax = ax === undefined ? new FloatParam(0, 1) : ax
		this.ay = ay === undefined ? new FloatParam(0, 1) : ay
		this.bend = bend === undefined ? new FloatParam(-0.4, 0.4) : bend
		this.cx = cx === undefined ? new FloatParam(0, 1) : cx
		this.cy = cy === undefined ? new FloatParam(0, 1) : cy
		this.thickness = thickness || new FloatParam(0.1, max(maxThickness || 1, 0.15))
	}

	b() {
		const centerX = (this.ax.value + this.cx.value) / 2
		const centerY = (this.ay.value + this.cy.value) / 2
		let normY = this.cx.value - this.ax.value
		let normX = -(this.cy.value - this.ay.value)
		// const hyp = Math.hypot(normX, normY) || 1
		// normX /= hyp
		// normY /= hyp
		const bx = centerX + this.bend.value * normX * 0.5
		const by = centerY + this.bend.value * normY * 0.5
		return { bx, by }
	}
	bx() { return this.b().bx }
	by() { return this.b().by }

	mutate(sd) {
		let { ax, ay, bend, cx, cy, thickness } = this
		const params = { ax, ay, bend, cx, cy, thickness }
		const key = random(['ax', 'ay', 'bend', 'cx', 'cy', 'thickness', 'thickness'])
		params[key] = params[key].mutate(sd)
		return new QuadraticBezierParam(
			params.ax, params.ay,
			params.bend,
			params.cx, params.cy,
			params.thickness,
			params.thickness.maxVal,
		)
	}
}

class FloatParam {
	constructor(minVal, maxVal, value) {
		this.minVal = minVal
		this.maxVal = maxVal
		this.value = value === undefined ? random(minVal, maxVal) : value
	}

	mutate(sd) {
		return new FloatParam(
			this.minVal,
			this.maxVal,
			constrain(
				randomGaussian(this.value, sd * (this.maxVal - this.minVal)),
				this.minVal,
				this.maxVal,
			),
		)
	}
}

// === Tab: beanFit ===
class BeanFitter {
	constructor(target, dilate) {
		const fboSize = 300
		this.fboSize = fboSize
		this.targetGraphic = createGraphics(fboSize, fboSize)
		this.targetGraphic.pixelDensity(1)
		this.beansGraphic = createGraphics(fboSize, fboSize)
		this.beansGraphic.pixelDensity(1)
		this.bestFbo = createFramebuffer({ width: fboSize, height: fboSize, density: 1 })

		this.target = target
		this.targetGraphic.push()
		this.targetGraphic.imageMode(CENTER)
		this.targetGraphic.translate(fboSize/2, fboSize/2)
		this.targetGraphic.scale(target.width > target.height ? fboSize/target.width : fboSize/target.height)
		this.targetGraphic.image(target, 0, 0)
		this.targetGraphic.pop()
		if (dilate) {
			for (let i = 0; i < 10; i++) {
				this.targetGraphic.filter(DILATE)
			}
		}
		this.targetGraphic.loadPixels()
		this.computeMaxThickness()

		this.params = new BeanParams([], this.maxThickness)
		this.bestParams = this.params
		this.segmentCost = 0.025
		this.score = 0
		this.bestScore = 0
	}

	remove() {
		this.targetGraphic.remove()
		this.beansGraphic.remove()
		this.bestFbo.remove()
	}

	computeMaxThickness() {
		let maxR = 0
		for (let i = 0; i < 500; i++) {
			const center = createVector(
				floor(random(this.fboSize)),
				floor(random(this.fboSize)),
			)
			const maxPossible = Math.min(this.fboSize-center.x, this.fboSize-center.y, center.x, center.y)
			let r;
			for (
				r = 1;
				r < maxPossible;
				r += 1
			) {
				const samples = min(80, ceil(r * TWO_PI));
				let ok = true
				for (let j = 0; j < samples; j++) {
					const angle = j/samples * TWO_PI
					const pt = createVector(
						round(center.x + r * cos(angle)),
						round(center.y + r * sin(angle)),
					)
					if (pt.x < 0 || pt.x >= this.fboSize || pt.y < 0 || pt.y >= this.fboSize) {
						continue
					}
					if (this.targetGraphic.pixels[4 * (pt.y * this.fboSize + pt.x) + 3] === 0) {
						ok = false
						break
					}
				}
				if (!ok) break
			}
			if (r > maxR) {
				maxR = r
			}
		}

		this.maxThickness = maxR ? 3 * maxR / this.fboSize : 1
	}

	optimize() {
		const lastParams = this.params
		const lastScore = this.score
		for (let i = 0; i < 4; i++) {
			this.params = this.params.mutate(max(this.score, 1/this.score)/100)
		}
		this.scoreParams()
		if (this.score > this.bestScore) {
			this.bestScore = this.score
			this.bestParams = this.params
			this.bestFbo.draw(() => {
				clear()
				imageMode(CENTER)
				image(this.beansGraphic, 0, 0)
			})
		}
		if (!(this.score > lastScore || random() < this.score / lastScore)) {
			this.params = lastParams
			this.score = lastScore
		}
		if (this.score < 0.5*this.bestScore && random(0.4) > this.score / this.bestScore) {
			this.params = this.bestParams
			this.score = this.bestScore
		}
	}

	draw() {
		push()
		imageMode(CENTER)
		image(this.targetGraphic, -this.beansGraphic.width, 0)
		image(this.beansGraphic, 0, 0)
		image(this.bestFbo, this.beansGraphic.width, 0)
		pop()
	}

	scoreParams() {
		this.drawBeans()
		this.beansGraphic.loadPixels()
		let intersection = 0
		let union = 0
		for (let i = 3; i < this.beansGraphic.pixels.length; i += 4) {
			const hasTarget = this.targetGraphic.pixels[i] > 0
			const hasBeans = this.beansGraphic.pixels[i] > 0
			if (hasTarget && hasBeans) intersection++
			if (hasTarget || hasBeans) union++
		}
		this.score = intersection / (union + 1e-6) - this.segmentCost * this.params.segments.length
	}

	drawBeans() {
		const { beansGraphic } = this
		beansGraphic.clear()
		beansGraphic.noFill()
		beansGraphic.stroke(0)
		for (const segment of this.params.segments) {
			beansGraphic.strokeWeight(segment.thickness.value * this.fboSize * 0.5)
			beansGraphic.beginShape()
			beansGraphic.vertex(...this.mapValues([segment.ax.value, segment.ay.value]))
			beansGraphic.quadraticVertex(
				...this.mapValues([
					segment.bx(), segment.by(),
					segment.cx.value, segment.cy.value,
				]),
			)
			beansGraphic.endShape()
		}
	}

	mapValues(values) {
		return values.map(v => map(v, 0, 1, 0, this.fboSize))
	}
}

// === Tab: beanRenderer ===
function createBeanRenderer() {
	// `createShaderPark` takes in a function that defines a shape using
	// the Shader Park API avaible here:
	// https://docs.shaderpark.com/references-js/
	// shaderParkCode is loaded in from shaderParkCode.js
	// Shader Park will covert the javascript into a shdaer for you
  sdf = createShaderPark(
		function() {
			let getSegmentA = glslFunc(`
			vec2 getSegmentA(float i) {
			  return (as[int(i)] - vec2(0.5)) * 0.5;
			}
			`)
			let getSegmentB = glslFunc(`
			vec2 getSegmentB(float i) {
			  return (bs[int(i)] - vec2(0.5)) * 0.5;
			}
			`)
			let getSegmentC = glslFunc(`
			vec2 getSegmentC(float i) {
			  return (cs[int(i)] - vec2(0.5)) * 0.5;
			}
			`)
			let getSegmentThickness = glslFunc(`
			float getSegmentThickness(float i) {
			  return (thicknesses[int(i)] * 0.5) * 0.5;
			}
			`)
			let getNumSegments = glslFunc(`
			float getNumSegments() {
			  return float(numSegments);
			}
			`)
			let getSmoothness = glslFunc(`
			float getSmoothness() {
			  return smoothness;
			}
			`)

			let dot2 = glslFunc(`
			float dot2(vec2 v) {
			  return dot(v,v);
			}
			`)

			let smoothUnion = glslFunc(`
			float opSmoothUnion( float d1, float d2, float k )
			{
					float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
					return mix( d2, d1, h ) - k*h*(1.0-h);
			}
			`)

			let sdfSegment = glslSDF(`
			//https://iquilezles.org/articles/distfunctions/
			float sdBezier( in vec3 pos3, in vec2 A, in vec2 B, in vec2 C, in float thickness )
			{
					vec2 pos = pos3.xy;
					vec2 a = B - A;
					vec2 b = A - 2.0*B + C;
					vec2 c = a * 2.0;
					vec2 d = A - pos;
					float kk = 1.0/dot(b,b);
					float kx = kk * dot(a,b);
					float ky = kk * (2.0*dot(a,a)+dot(d,b)) / 3.0;
					float kz = kk * dot(d,a);      
					float res = 0.0;
					float p = ky - kx*kx;
					float p3 = p*p*p;
					float q = kx*(2.0*kx*kx-3.0*ky) + kz;
					float h = q*q + 4.0*p3;
					if( h >= 0.0) 
					{ 
							h = sqrt(h);
							vec2 x = (vec2(h,-h)-q)/2.0;
							vec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));
							float t = clamp( uv.x+uv.y-kx, 0.0, 1.0 );
							res = dot2(d + (c + b*t)*t);
					}
					else
					{
							float z = sqrt(-p);
							float v = acos( q/(p*z*2.0) ) / 3.0;
							float m = cos(v);
							float n = sin(v)*1.732050808;
							vec3  t = clamp(vec3(m+m,-n-m,n-m)*z-kx,0.0,1.0);
							res = min( dot2(d+(c+b*t.x)*t.x),
												 dot2(d+(c+b*t.y)*t.y) );
							// the third root cannot be the closest
							// res = min(res,dot2(d+(c+b*t.z)*t.z));
					}
					return sqrt( res + pos3.z*pos3.z ) - thickness * 0.5;
			}`)

			let sdfSegments = glslSDF(`
			float glslSegments(in vec3 p) {
				float d = sdBezier(p, as[0], bs[0], cs[0], thicknesses[0]);
				for (int i = 1; i < 8; i++) {
					if (i == numSegments) break;
					d = opSmoothUnion(d, sdBezier(p, as[i], bs[i], cs[i], thicknesses[i]), smoothness);
				}
				return d;
			}
			`)

			color(0,0,0)
			sdfSegments()
			// blend(getSmoothness())
			// for (let i = 0; i < 8; i++) {
			// 	if (i < getNumSegments()) {
			// 		sdfSegment(getSegmentA(i), getSegmentB(i), getSegmentC(i), getSegmentThickness(i))
			// 	}
			// }
		},
		{
			scale: 1.0, 
			drawGeometry: () => sphere(400)
		}
	);

	sdf.shader._fragSrc = sdf.shader._fragSrc.replace(
		'precision highp float;',
		`precision highp float;
		uniform vec2 as[8];
		uniform vec2 bs[8];
		uniform vec2 cs[8];
		uniform float thicknesses[8];
		uniform int numSegments;
		uniform float smoothness;
		uniform sampler2D spheremap;
		`
	).replace(
		'outputColor = col.color;',
		`
		vec3 n = reflect(
			normalize(p - cameraPosition),
			normal
			// normalize((uModelViewMatrix * vec4(normal, 0.)).xyz)
		);
		float phi = acos( n.y );
		float theta = 0.0;
		theta = acos(n.x / sin(phi));
		float sinTheta = n.z / sin(phi);
		if (sinTheta < 0.0) {
			// Turn it into -theta, but in the 0-2PI range
			theta = 2.0 * PI - theta;
		}
		theta = theta / (2.0 * 3.14159);
		phi = phi / 3.14159 ;
		vec2 angles = vec2( fract(theta + 0.25), 1.0 - phi );

		outputColor = pow(texture(spheremap, angles).xyz + col.color, vec3(2.));
		`
	)

	return {
		draw: (params, smoothness = 0.2) => {
			const as = params.segments.flatMap((seg) => [
				0.75 * (seg.ax.value - 0.5),
				0.75 * (seg.ay.value - 0.5),
			])
			const bs = params.segments.flatMap((seg) => {
				return [
					0.75 * (seg.bx() - 0.5),
					0.75 * (seg.by() - 0.5),
				]
			})
			const cs = params.segments.flatMap((seg) => [
				0.75 * (seg.cx.value - 0.5),
				0.75 * (seg.cy.value - 0.5),
			])
			const thicknesses = params.segments.flatMap((seg) => [
				seg.thickness.value * 0.5 * 0.75,
			])
			sdf.shader.setUniform('as', as)
			sdf.shader.setUniform('bs', bs)
			sdf.shader.setUniform('cs', cs)
			sdf.shader.setUniform('thicknesses', thicknesses)
			sdf.shader.setUniform('numSegments', params.segments.length)
			sdf.shader.setUniform('smoothness', smoothness)
			sdf.shader.setUniform('spheremap', spheremap)
			push()
			sdf.draw()
			pop()
		}
	}
}

